// Real geography from Natural Earth (public domain), loaded lazily with the globe chunk:
//   - world-atlas 1:110m countries (flat fallback map) and 1:50m countries (globe fill, borders, coastlines)
//   - src/data/country-labels.json  [name, lat, lng, areaKm2]         label point inside each country
//   - src/data/cities.json          [name, lat, lng, scalerank, population, capital(0|1|2), country]
//   - src/data/admin1-lines.json    state/province boundaries as flat [lng, lat, lng, lat, ...] arrays
// The three src/data files are generated by scripts/geodata/ (see displaceos-frontend/README.md).
import { feature, mesh } from 'topojson-client';

let coarse = null;
let detailed = null;
let places = null;
let admin1 = null;

export async function loadWorld() {
  if (coarse) return coarse;
  const topo = (await import('world-atlas/countries-110m.json')).default;
  coarse = {
    countries: feature(topo, topo.objects.countries),
    borders: mesh(topo, topo.objects.countries, (a, b) => a !== b),
    land: feature(topo, topo.objects.land),
  };
  return coarse;
}

export async function loadDetailedWorld() {
  if (detailed) return detailed;
  const topo = (await import('world-atlas/countries-50m.json')).default;
  detailed = {
    countries: feature(topo, topo.objects.countries),
    borders: mesh(topo, topo.objects.countries, (a, b) => a !== b),
    coast: mesh(topo, topo.objects.countries, (a, b) => a === b),
  };
  return detailed;
}

export async function loadPlaces() {
  if (places) return places;
  const [cities, countries] = await Promise.all([import('../../data/cities.json'), import('../../data/country-labels.json')]);
  places = { cities: cities.default, countries: countries.default };
  return places;
}

export async function loadAdmin1() {
  if (admin1) return admin1;
  admin1 = (await import('../../data/admin1-lines.json')).default;
  return admin1;
}

// Rings as continuous longitude sequences (no ±180 jumps), so they can be drawn on an equirectangular canvas.
export function unwrapRing(ring) {
  const out = [];
  let offset = 0;
  let prev = null;
  for (const [lng, lat] of ring) {
    if (prev !== null) {
      const d = lng - prev;
      if (d > 180) offset -= 360;
      else if (d < -180) offset += 360;
    }
    out.push([lng + offset, lat]);
    prev = lng;
  }
  return out;
}

export function polygonsOf(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'Polygon') return [geometry.coordinates];
  if (geometry.type === 'MultiPolygon') return geometry.coordinates;
  return [];
}

export function linesOf(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'LineString') return [geometry.coordinates];
  if (geometry.type === 'MultiLineString') return geometry.coordinates;
  return [];
}

// Position buffer for THREE.LineSegments from polylines given as [[lng,lat],...] or flat [lng,lat,lng,lat,...].
export function lineSegmentPositions(lines, radius, latLngToVec) {
  let count = 0;
  for (const l of lines) count += (Array.isArray(l[0]) ? l.length : l.length / 2) - 1;
  const out = new Float32Array(Math.max(0, count) * 6);
  let o = 0;
  for (const l of lines) {
    const flat = !Array.isArray(l[0]);
    const n = flat ? l.length / 2 : l.length;
    let prev = null;
    for (let i = 0; i < n; i++) {
      const lng = flat ? l[i * 2] : l[i][0];
      const lat = flat ? l[i * 2 + 1] : l[i][1];
      const v = latLngToVec(lat, lng, radius);
      if (prev) {
        out[o++] = prev[0];
        out[o++] = prev[1];
        out[o++] = prev[2];
        out[o++] = v[0];
        out[o++] = v[1];
        out[o++] = v[2];
      }
      prev = v;
    }
  }
  return out.subarray(0, o);
}
